observation.command:
cd /workspace/.build-logs && awk '
NR==74 {
  print "    for pp in $(find \"$d\" -maxdepth 2 -name pyproject.toml | sort); do"
  print "      ( cd \"$(dirname \"$pp\")\" && timeout 300 uv lock >> \"$LOGS/wave2-relock.log\" 2>&1 )"
  print "    done"
  next
}
{ print }
' wave2.sh > wave2.sh.new && mv wave2.sh.new wave2.sh && chmod +x wave2.sh && sed -n '70,80p' wave2.sh && bash -n wave2.sh && echo "SYNTAX OK"
